#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007;

vector<int> parent, sz;

int find_set(int v) {
    if (parent[v] == v) return v;
    return parent[v] = find_set(parent[v]);
}

void unite(int a, int b) {
    a = find_set(a);
    b = find_set(b);

    if (a == b) return;
    if (sz[a] < sz[b]) swap(a, b);

    parent[b] = a;
    sz[a] += sz[b];
}

ll mod_pow(ll base, ll exponent) {
    ll result = 1;
    base %= MOD;

    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    ll m;
    cin >> n >> m >> k;

    parent.resize(n + 1);
    sz.assign(n + 1, 1);
    iota(parent.begin(), parent.end(), 0);

    for (int left = 1; left + k - 1 <= n; ++left) {
        int i = left;
        int j = left + k - 1;

        while (i < j) {
            unite(i, j);
            ++i;
            --j;
        }
    }

    int components = 0;
    for (int i = 1; i <= n; ++i) {
        if (find_set(i) == i) ++components;
    }

    cout << mod_pow(m, components);
    return 0;
}

